'use strict';
const assert=require('assert/strict'),fs=require('fs'),path=require('path'),os=require('os');
const {LauncherService}=require('../src/launcher-service');const {seedProjectContext}=require('./project-context-fixtures');const {seedBundledMods,workshopBundle}=require('./bundled-mod-fixtures');
const {spawnSync}=require('child_process');
const {zip,write}=require('./workbench-fixtures');
const root=path.resolve(__dirname,'..'),temporary=fs.mkdtempSync(path.join(os.tmpdir(),'enderloom-bundled-mods-'));
const service=new LauncherService({rootDir:root,dataDir:path.join(temporary,'data'),env:{ENDERLOOM_CURSEFORGE_API_KEY:'qa-offline-cache-only'}});
(async()=>{
 const {first}=await seedProjectContext(service),fixture=await seedBundledMods(service,first),args={provider:'modrinth',projectId:'alpha'};
 const get=()=>service.request('get_project_context',args);
 let context=await get(),target=context.targets[0];
 assert.deepEqual(target.bundled_mods.map(m=>m.mod_id).sort(),['bundled_helper','neo_bundle','quilt_core']);
 assert.equal(target.bundled_mods.find(m=>m.mod_id==='bundled_helper').sha256,fixture.sha256);assert(target.bundled_mods.every(m=>m.sha256.length===64));
 assert(!target.project_mod_ids.includes('bundled_helper'),'Bundled dependency was misidentified as the containing project');
 assert.equal(target.dependencies.find(d=>d.owner==='identity_fixture'&&d.mod_id==='bundled_helper').installed_targets[0].bundled,true);
 assert.equal(target.dependencies.find(d=>d.owner==='quilt_core').archive_path,'META-INF/jars/helper.jar!/nested/quilt.jar!/');
 assert.equal(target.dependencies.find(d=>d.owner==='legacy_addon').version_range,'[1,3)');
 assert(target.warnings.some(w=>w.includes('Unsafe bundled JAR path')));assert(target.warnings.some(w=>w.includes('missing.jar')));assert(target.warnings.some(w=>w.includes('broken.jar')));
 assert(!JSON.stringify(target).includes('unrelated_example'));
 assert(fs.readFileSync(path.join(first.dir,'mods/first.jar')).equals(fixture.bytes),'Inspection changed the source JAR');
 const original=fs.statSync(path.join(first.dir,'mods/first.jar')),changed=workshopBundle('4.1');assert.equal(changed.bytes.length,fixture.bytes.length);
 fs.writeFileSync(path.join(first.dir,'mods/first.jar'),changed.bytes);fs.utimesSync(path.join(first.dir,'mods/first.jar'),original.atime,original.mtime);
 target=(await get()).targets[0];assert.equal(target.bundled_mods.find(m=>m.mod_id==='bundled_helper').mod_version,'4.1','Cache ignored a same-size/time edit');assert.equal(target.bundled_mods.find(m=>m.mod_id==='bundled_helper').sha256,changed.sha256);
 fs.renameSync(path.join(first.dir,'mods/first.jar'),path.join(first.dir,'mods/first.jar.disabled'));
 context=await get();target=context.targets[0];assert(target.bundled_mods.every(m=>!m.enabled));assert(target.dependencies.filter(d=>d.archive_path).every(d=>!d.source_enabled));
 await service.close();const cli=spawnSync(path.join(root,'native/target/debug/enderloom.exe'),['--data-dir',service.dataDir,'operation','run','get_project_context','--json'],{input:JSON.stringify(args),encoding:'utf8',windowsHide:true,timeout:30000});assert.equal(cli.status,0,cli.stderr);assert.deepEqual(JSON.parse(cli.stdout).result.targets,context.targets);
 const guard=await service.request('create_instance',{name:'Bundled comparison guard',versionId:'1.20.1',loader:'fabric',loaderVersion:'0.16.0'});
 write(guard.dir,'mods/carrier.jar',zip({'fabric.mod.json':JSON.stringify({id:'carrier',version:'1',jars:[{file:'library.jar'}]}),'library.jar':zip({'fabric.mod.json':'{"id":"nested_library","version":"1"}'})}));
 write(guard.dir,'mods/uses-library.jar',zip({'fabric.mod.json':JSON.stringify({id:'uses_library',version:'1',depends:{nested_library:'*'}})}));
 await assert.rejects(service.request('compare_mod_startup',{instanceId:guard.id,fileName:'carrier.jar',seconds:15,repeats:1}),/Removing this mod would break required dependents: uses-library.jar/);
 write(guard.dir,'mods/conditional.jar',zip({'quilt.mod.json':JSON.stringify({schema_version:1,quilt_loader:{id:'conditional',version:'1',group:'org.example',depends:[['left','right']]}})}));
 await assert.rejects(service.request('compare_mod_startup',{instanceId:guard.id,fileName:'conditional.jar',seconds:15,repeats:1}),/Conditional dependency declarations require loader resolution/);
 console.log(JSON.stringify({passed:true,bundledMods:3,verified:['recursive Fabric and Quilt declarations','Forge/NeoForge JarJar metadata','legacy mcmod.info dependencies','exact SHA-256','duplicate nested path deduplication','unlisted JAR excluded','unsafe and missing entries reported','corrupt sibling isolation','same-size/time cache invalidation','disabled container provenance','source bytes preserved','service/CLI restart parity']}));
})().catch(e=>{console.error(e);process.exitCode=1}).finally(()=>service.close());
